// What `kubeadm init` and `kubeadm join` leave on a cluster, from the reference the real kubeadm
// v1.37.2 produced (kubeadm/reference.ts, generated by `npm run kubeadm:capture`; rank 1):
// files on the nodes, then the API objects kubeadm creates, then what the components it starts
// would create (mirror Pods, DaemonSet Pods, CoreDNS through the controllers).
//
// Stand-ins until their phases (STATUS.md, temporary shortcuts):
// - No certificates: /etc/kubernetes/pki is not written and kubeconfigs and cluster-info carry no
//   certificate data (the certificate format is phase 25b's; PKI checks phase 28).
// - RBAC objects (Roles, ClusterRoles and their bindings) are not stored: the API server serves no
//   rbac.authorization.k8s.io kinds yet (phase 20a).
// - The control plane's mirror Pods and kube-proxy's Pods are created as running objects; phase 27
//   (static Pods through the kubelet) and 18a (the DaemonSet controller) create them for real.
//   CoreDNS is created by the Deployment and ReplicaSet controllers and bound by the scheduler; it
//   stays Pending until the kubelet exists (phase 06b).

import type { Ctx } from '@simlab/kernel';
import { createFs, ROOT_CRED } from '@simlab/host';
import type { Json, JsonObject } from '../apimachinery/json.ts';
import { cloneJson, isObject } from '../apimachinery/json.ts';
import { formatMicroTime, timeOf } from '../apimachinery/time.ts';
import type { ApiServerConfig } from '../apiserver/config.ts';
import { createClient, type Client } from '../client/client.ts';
import { encodeBase64, utf8Bytes } from '../apimachinery/base64.ts';
import { fnv128aHex } from '../controllers/endpointslice/hash.ts';
import { computeHash } from '../controllers/hash/podtemplate.ts';
import { controlPlaneNode, type ClusterDef, type ClusterNodeDef } from './cluster.ts';
import { KUBEADM_FILES, KUBEADM_OBJECT_ORDER, KUBEADM_OBJECTS, KUBELET_CONF_FINALIZED, STATIC_POD_MANIFESTS } from './kubeadm/reference.ts';

/** The reference's control-plane address; the topology's own replaces it (both are 172.16.0.10 today). */
const REFERENCE_CP_IP = '172.16.0.10';
const REFERENCE_CP_NAME = 'controlplane';

/** Drops the certificate and key data lines, which stand for PEM data the simulator has no format for yet. */
function withoutCertData(text: string): string {
  return text
    .split('\n')
    .filter((l) => !/^\s*(certificate-authority-data|client-certificate-data|client-key-data): <<(cert|key):[^>]*>>$/.test(l))
    .join('\n');
}

function forNode(text: string, def: ClusterDef): string {
  const cp = controlPlaneNode(def);
  return text.split(REFERENCE_CP_IP).join(cp.ip).split(`name: ${REFERENCE_CP_NAME}`).join(`name: ${cp.name}`);
}

function mkdirs(fs: ReturnType<typeof createFs>, path: string, mode: number): void {
  const parts = path.split('/').filter(Boolean);
  let cur = '';
  for (const p of parts) {
    cur += `/${p}`;
    try {
      fs.stat(cur);
    } catch {
      fs.mkdir(cur, mode);
    }
  }
}

function writeFile(fs: ReturnType<typeof createFs>, path: string, text: string, mode: number): void {
  mkdirs(fs, path.slice(0, path.lastIndexOf('/')) || '/', 0o755);
  fs.writeFile(path, text, { mode, exclusive: true });
  fs.chmod(path, mode);
}

/**
 * The binaries of the kubeadm, kubelet and kubectl packages (pkgs.k8s.io, installed to /usr/bin),
 * with the sizes of the v1.37.2 release binaries they package: kubeadm and kubectl measured in
 * .upstream/bin/v1.37.2/, kubelet from dl.k8s.io's Content-Length (2026-11-16). A program that is
 * not simulated yet prints the `[sim]` notice when run.
 */
const KUBERNETES_BINARIES: readonly [string, number][] = [
  ['kubeadm', 74_588_322],
  ['kubectl', 61_890_722],
  ['kubelet', 61_264_137],
];

/**
 * Files on each node. The control plane gets everything init writes (with kubelet.conf in the
 * form the kubelet-finalize phase leaves); a worker gets what join writes: kubelet.conf, the kubelet
 * configuration downloaded from the kubelet-config ConfigMap, the flags file and the empty
 * manifest directory. Root's kubeconfig is a copy of admin.conf, as kubeadm's closing
 * instructions say (`mkdir -p $HOME/.kube; sudo cp -i /etc/kubernetes/admin.conf $HOME/.kube/config`).
 */
export function installKubeadmFiles(ctx: Ctx, def: ClusterDef): void {
  for (const n of def.nodes) {
    const fs = createFs(ctx, n.name, { cred: ROOT_CRED, umask: 0o022 });
    for (const [name, size] of KUBERNETES_BINARIES) fs.installProgram(`/usr/bin/${name}`, name, { size, mode: 0o755 });
    mkdirs(fs, '/etc/kubernetes/manifests', 0o755);
    for (const f of KUBEADM_FILES) {
      const isKubelet = f.path.startsWith('/var/lib/kubelet/');
      if (!n.controlPlane && !isKubelet) continue;
      if (f.path === '/etc/kubernetes/kubelet.conf') continue;
      writeFile(fs, f.path, forNode(withoutCertData(f.text), def), parseInt(f.mode, 8));
    }
    writeFile(fs, '/etc/kubernetes/kubelet.conf', forNode(withoutCertData(n.controlPlane ? KUBELET_CONF_FINALIZED : WORKER_KUBELET_CONF), def), 0o600);
    if (n.controlPlane) {
      mkdirs(fs, '/var/lib/etcd', 0o700);
      fs.chmod('/var/lib/etcd', 0o700);
      const admin = KUBEADM_FILES.find((f) => f.path === '/etc/kubernetes/admin.conf');
      if (admin) {
        mkdirs(fs, '/root/.kube', 0o755);
        writeFile(fs, '/root/.kube/config', forNode(withoutCertData(admin.text), def), 0o600);
      }
    }
  }
}

/**
 * A joined worker's kubelet.conf, which the kubelet writes itself after TLS bootstrap
 * (rank 2, source-derived: pkg/kubelet/certificate/bootstrap/bootstrap.go
 * writeKubeconfigFromBootstrapping, serialized by clientcmd.WriteToFile in the same layout as the
 * captured control-plane file). Mode 0600 like every kubeconfig clientcmd writes.
 */
const WORKER_KUBELET_CONF = `apiVersion: v1
clusters:
- cluster:
    certificate-authority-data: <<cert:ca>>
    server: https://${REFERENCE_CP_IP}:6443
  name: default-cluster
contexts:
- context:
    cluster: default-cluster
    namespace: default
    user: default-auth
  name: default-context
current-context: default-context
kind: Config
users:
- name: default-auth
  user:
    client-certificate: /var/lib/kubelet/pki/kubelet-client-current.pem
    client-key: /var/lib/kubelet/pki/kubelet-client-current.pem
`;

const meta = (o: JsonObject): JsonObject => (isObject(o.metadata) ? o.metadata : {});

/** Kinds the simulated API server stores, as `apiVersion/kind` → resource path. */
const RESOURCES: Record<string, string> = {
  'v1/ConfigMap': 'v1/configmaps',
  'v1/Secret': 'v1/secrets',
  'v1/ServiceAccount': 'v1/serviceaccounts',
  'v1/Service': 'v1/services',
  'apps/v1/Deployment': 'apps/v1/deployments',
  'apps/v1/DaemonSet': 'apps/v1/daemonsets',
};

/** [a-z0-9]: the bootstrap token alphabet (cmd/kubeadm/app/util/bootstraptoken, bootstraputil.GenerateBootstrapToken). */
const TOKEN_CHARS = 'abcdefghijklmnopqrstuvwxyz0123456789';

const base64 = (s: string): string => encodeBase64(utf8Bytes(s));

/** Substitutes the reference's tokens and the topology's address in an object kubeadm creates. */
function prepare(o: JsonObject, def: ClusterDef, token: { id: string; secret: string; expiration: string }): JsonObject {
  const walk = (v: Json): Json => {
    if (Array.isArray(v)) return v.map(walk);
    if (isObject(v)) {
      const out: JsonObject = {};
      for (const k of Object.keys(v)) out[k] = walk(v[k] as Json);
      return out;
    }
    if (typeof v !== 'string') return v;
    let s = withoutCertData(v);
    s = s.split('<<base64:token:id>>').join(base64(token.id)).split('<<base64:token:secret>>').join(base64(token.secret)).split('<<base64:token:expiration>>').join(base64(token.expiration));
    s = s.split('<<token:id>>').join(token.id);
    return forNode(s, def);
  };
  const out = walk(cloneJson(o as Json)) as JsonObject;
  // kubeadm sends resourceVersion "0" on a few objects (it builds them for CreateOrUpdate); a
  // create ignores it upstream, and the simulated pipeline does too only without it.
  const m = meta(out);
  if (m.resourceVersion !== undefined) delete m.resourceVersion;
  return out;
}

function must(r: ReturnType<Client['request']>, what: string): JsonObject {
  if (!r.ok) throw new Error(`kubeadm topology: ${what}: ${JSON.stringify(r)}`);
  return r.object as JsonObject;
}

/** The objects kubeadm init creates, in its order, for the kinds the API server serves. */
function createKubeadmObjects(ctx: Ctx, def: ClusterDef, client: Client): void {
  const rnd = ctx.random('k8s.kubeadm.token');
  // kubeadm's default token TTL is 24 h (constants.DefaultTokenDuration); expiration is RFC 3339.
  const token = { id: rnd.chars(6, TOKEN_CHARS), secret: rnd.chars(16, TOKEN_CHARS), expiration: timeOf(ctx.now + 24 * 3600_000) };
  const seen: Record<string, number> = {};
  for (const ref of KUBEADM_OBJECT_ORDER) {
    const list = KUBEADM_OBJECTS[ref.kind] ?? [];
    const i = seen[ref.kind] ?? 0;
    seen[ref.kind] = i + 1;
    const obj = list[i];
    const resource = RESOURCES[`${ref.apiVersion}/${ref.kind}`];
    if (!obj || !resource) continue;
    const body = prepare(obj as unknown as JsonObject, def, token);
    const ns = typeof meta(body).namespace === 'string' ? (meta(body).namespace as string) : undefined;
    must(client.resource(resource).create(ns, body), `${ref.kind} ${ref.name}`);
  }
}

// ---- seeded running Pods ----

function containerId(ctx: Ctx): string {
  return `containerd://${ctx.random('k8s.seed.container-id').chars(64, '0123456789abcdef')}`;
}

/** A running Pod's status as a kubelet reports it (phase 06b's kubelet replaces this). */
function runningStatus(ctx: Ctx, pod: JsonObject, hostIP: string, podIP: string, now: string): JsonObject {
  const spec = isObject(pod.spec) ? pod.spec : {};
  const containers = (Array.isArray(spec.containers) ? spec.containers : []) as JsonObject[];
  const cond = (type: string): JsonObject => ({ type, status: 'True', lastProbeTime: null, lastTransitionTime: now });
  return {
    phase: 'Running',
    conditions: [cond('PodReadyToStartContainers'), cond('Initialized'), cond('Ready'), cond('ContainersReady'), cond('PodScheduled')],
    hostIP,
    hostIPs: [{ ip: hostIP }],
    podIP,
    podIPs: [{ ip: podIP }],
    startTime: now,
    containerStatuses: containers.map((c) => ({
      name: c.name as string,
      image: c.image as string,
      imageID: '',
      containerID: containerId(ctx),
      ready: true,
      restartCount: 0,
      started: true,
      state: { running: { startedAt: now } },
    })),
  };
}

/** The kubelet's mirror Pod of a static Pod manifest on `node` (pkg/kubelet/config/common.go applyDefaults, pod/mirror_client.go). */
function mirrorPod(manifest: JsonObject, path: string, node: ClusterNodeDef, nodeUID: string, seen: string): JsonObject {
  const pod = cloneJson(manifest as Json) as JsonObject;
  const m = meta(pod);
  const spec = isObject(pod.spec) ? pod.spec : {};
  // The config hash: upstream an FNV-128a of the Pod's Go struct dump plus host and file; here of
  // the manifest's JSON (docs/FIDELITY.md DIV-019).
  const bytes = [...utf8Bytes(`${JSON.stringify(manifest)}host:${node.name}file:${path}`)].map((c) => c.charCodeAt(0));
  const hash = fnv128aHex(bytes);
  m.name = `${String(m.name)}-${node.name}`;
  m.annotations = {
    ...(isObject(m.annotations) ? m.annotations : {}),
    'kubernetes.io/config.hash': hash,
    'kubernetes.io/config.mirror': hash,
    'kubernetes.io/config.seen': seen,
    'kubernetes.io/config.source': 'file',
  };
  m.ownerReferences = [{ apiVersion: 'v1', kind: 'Node', name: node.name, uid: nodeUID, controller: true }];
  spec.nodeName = node.name;
  // A static Pod tolerates every NoExecute taint (applyDefaults, isFile).
  spec.tolerations = [...((Array.isArray(spec.tolerations) ? spec.tolerations : []) as JsonObject[]), { operator: 'Exists', effect: 'NoExecute' }];
  pod.spec = spec;
  delete pod.status;
  return pod;
}

/** Nanosecond RFC 3339 time of the kubelet's first sighting (kubetypes.Timestamp.GetString). */
function seenTime(ms: number): string {
  return formatMicroTime(ms * 1000).replace(/\.(\d{6})Z$/, (_, us: string) => `.${us}000Z`);
}

function seedStaticPods(ctx: Ctx, def: ClusterDef, server: ApiServerConfig, nodeUIDs: Record<string, string>): void {
  const cp = controlPlaneNode(def);
  const client = createClient(ctx, server, { username: `system:node:${cp.name}`, groups: ['system:nodes', 'system:authenticated'] });
  const now = timeOf(ctx.now);
  const names = ['etcd', 'kube-apiserver', 'kube-controller-manager', 'kube-scheduler'];
  (STATIC_POD_MANIFESTS as unknown as JsonObject[]).forEach((manifest, i) => {
    const path = `/etc/kubernetes/manifests/${names[i] ?? 'pod'}.yaml`;
    const body = JSON.parse(forNode(JSON.stringify(manifest), def)) as JsonObject;
    const created = must(client.resource('v1/pods').create('kube-system', mirrorPod(body, path, cp, nodeUIDs[cp.name] ?? '', seenTime(ctx.now))), `mirror Pod ${path}`);
    // hostNetwork: the Pod's IP is the node's.
    must(client.resource('v1/pods').updateStatus('kube-system', { ...created, status: runningStatus(ctx, created, cp.ip, cp.ip, now) }), `mirror Pod status ${path}`);
  });
}

/**
 * kube-proxy's Pods as the DaemonSet controller creates them (pkg/controller/daemon:
 * generateName `<ds>-`, the controller-revision-hash and pod-template-generation labels, a required
 * node affinity on metadata.name, the tolerations util.AddOrUpdateDaemonPodTolerations adds), bound
 * and running; and the DaemonSet's status.
 */
function seedDaemonSetPods(ctx: Ctx, def: ClusterDef, client: Client): void {
  const dsClient = client.resource('apps/v1/daemonsets');
  const r = dsClient.get('kube-system', 'kube-proxy');
  if (!r.ok) return;
  const ds = r.object as JsonObject;
  const dsSpec = ds.spec as JsonObject;
  const template = dsSpec.template as JsonObject;
  const hash = computeHash(template);
  const now = timeOf(ctx.now);
  const rnd = ctx.random('k8s.seed.daemonset-suffix');
  const podClient = client.resource('v1/pods');
  for (const n of def.nodes) {
    const tm = meta(template);
    const tspec = cloneJson(template.spec as Json) as JsonObject;
    const tolerations = (Array.isArray(tspec.tolerations) ? tspec.tolerations : []) as JsonObject[];
    // util.AddOrUpdateDaemonPodTolerations (pkg/controller/daemon/util/daemonset_util.go).
    const add: JsonObject[] = [
      { key: 'node.kubernetes.io/not-ready', operator: 'Exists', effect: 'NoExecute' },
      { key: 'node.kubernetes.io/unreachable', operator: 'Exists', effect: 'NoExecute' },
      { key: 'node.kubernetes.io/disk-pressure', operator: 'Exists', effect: 'NoSchedule' },
      { key: 'node.kubernetes.io/memory-pressure', operator: 'Exists', effect: 'NoSchedule' },
      { key: 'node.kubernetes.io/pid-pressure', operator: 'Exists', effect: 'NoSchedule' },
      { key: 'node.kubernetes.io/unschedulable', operator: 'Exists', effect: 'NoSchedule' },
      ...(tspec.hostNetwork === true ? [{ key: 'node.kubernetes.io/network-unavailable', operator: 'Exists', effect: 'NoSchedule' }] : []),
    ];
    tspec.tolerations = [...tolerations, ...add];
    // util.ReplaceDaemonSetPodNodeNameNodeAffinity.
    tspec.affinity = { nodeAffinity: { requiredDuringSchedulingIgnoredDuringExecution: { nodeSelectorTerms: [{ matchFields: [{ key: 'metadata.name', operator: 'In', values: [n.name] }] }] } } };
    tspec.nodeName = n.name;
    const name = `kube-proxy-${rnd.chars(5, 'bcdfghjklmnpqrstvwxz2456789')}`;
    const body: JsonObject = {
      apiVersion: 'v1',
      kind: 'Pod',
      metadata: {
        name,
        namespace: 'kube-system',
        labels: { ...(isObject(tm.labels) ? tm.labels : {}), 'controller-revision-hash': hash, 'pod-template-generation': '1' },
        ownerReferences: [{ apiVersion: 'apps/v1', kind: 'DaemonSet', name: 'kube-proxy', uid: meta(ds).uid as string, controller: true, blockOwnerDeletion: true }],
      },
      spec: tspec,
    };
    const created = must(podClient.create('kube-system', body), `kube-proxy Pod on ${n.name}`);
    must(podClient.updateStatus('kube-system', { ...created, status: runningStatus(ctx, created, n.ip, n.ip, now) }), `kube-proxy Pod status on ${n.name}`);
  }
  const count = def.nodes.length;
  must(
    dsClient.updateStatus('kube-system', {
      ...ds,
      status: { currentNumberScheduled: count, desiredNumberScheduled: count, numberAvailable: count, numberMisscheduled: 0, numberReady: count, observedGeneration: 1, updatedNumberScheduled: count },
    }),
    'kube-proxy DaemonSet status',
  );
}

/** Everything kubeadm and the seeded components create in the API. */
export function seedKubeSystem(ctx: Ctx, def: ClusterDef, server: ApiServerConfig, nodeUIDs: Record<string, string>): void {
  // kubeadm acts with admin.conf (group kubeadm:cluster-admins); no authorization exists yet.
  const client = createClient(ctx, server, { username: 'kubernetes-admin', groups: ['kubeadm:cluster-admins', 'system:authenticated'] });
  createKubeadmObjects(ctx, def, client);
  seedStaticPods(ctx, def, server, nodeUIDs);
  seedDaemonSetPods(ctx, def, client);
}
